function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 50) return 'words needs 1 to 50 strings.';
  if (!words.every(w => typeof w === 'string' && /^[a-z]{2}$/.test(w))) return 'Each word is exactly two lowercase letters.';
  if (new Set(words).size !== words.length) return 'The words must be distinct.';
  return null;
}

