function maximumNumberOfStringPairs(words) {
  const seen = new Set();
  let pairs = 0;

  for (const word of words) {
    const reversed = word[1] + word[0];
    if (seen.has(reversed)) {
      pairs++;
    }
    seen.add(word);
  }
  return pairs;
}

