function maximumNumberOfStringPairs(words) {
  const used = new Array(words.length).fill(false);
  let count = 0;
  for (let i = 0; i < words.length; i++) {
    for (let j = i + 1; j < words.length; j++) {
      if (!used[i] && !used[j] && words[i] === words[j].split('').reverse().join('')) {
        used[i] = true;
        used[j] = true;
        count++;
      }
    }
  }
  return count;
}

