function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  // A small alphabet means a word's reverse is often present too.
  const k = size === 'large' ? 8 + Math.floor(rand() * 19) : 1 + Math.floor(rand() * 4);
  const all = [];
  for (let a = 0; a < k; a++) for (let b = 0; b < k; b++) all.push(letters[a] + letters[b]);
  for (let i = all.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [all[i], all[j]] = [all[j], all[i]];
  }
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * Math.min(all.length, 9));
  return [all.slice(0, n)];
}
